import{S as t,o as i,c as n,a9 as o,B as r}from"./chunks/framework.DxG24V0C.js";const d="/agentsrc/images/codex/07-thread-isolation.svg",h="/agentsrc/images/codex/07-agent-communication.svg",k=JSON.parse('{"title":"Codex 多 Agent 编排：如何像管理线程一样管理 AI 团队？","description":"","frontmatter":{"title":"Codex 多 Agent 编排：如何像管理线程一样管理 AI 团队？"},"headers":[],"relativePath":"codex/07-multi-agents.md","filePath":"codex/07-multi-agents.md","lastUpdated":1788847143000}'),p={name:"codex/07-multi-agents.md"},A=Object.assign(p,{setup(l){const a=[{question:"在处理复杂并行任务时，如果仅使用单体 Agent，最容易导致哪种负面后果？",options:["由于缺乏多线程支持，单体 Agent 无法同时发起多个 HTTP 请求","不同任务的信息高度交织会导致 Token 极速消耗并引发逻辑断层","单体 Agent 的本地 SQLite 数据库在写入并发日志时极易发生表锁死","操作系统会强制限制单个进程能够使用的最大内存上下文空间"],correct:1,explanation:"多线作战会让大量无关信息充斥上下文，不仅干扰推理，还会迅速撑爆 Token 预算，频繁触发压缩，最终导致局部细节丢失和逻辑断层。"},{question:"在 Codex 的 ThreadManager 架构中，子 Agent（CodexThread）是如何获得它的沙箱权限和指令策略的？",options:["子 Agent 拥有默认的绝对独立沙箱，完全不受父任务的影响","子 Agent 默认从父 Turn 的有效配置中派生或继承权限，并可通过角色配置调整","子 Agent 必须每次在启动前强制要求用户在终端重新授权输入密码","子 Agent 统一采用全局的只读沙箱策略，不允许执行任何写入操作"],correct:1,explanation:"子 Agent 拥有独立的对话上下文（Session），但其安全权限（如 Exec Policy 和 approval_policy）通常是从父 Turn 派生或继承的。"},{question:"对比 V1 和 V2 版本的 Agent 通信机制，V2 的 AgentPath 带来了什么核心改变？",options:["V2 使用文件系统的真实路径替换了内存通信，将所有消息持久化到磁盘文件中","V2 通过静态生成的层级路径（如 /root/researcher）进行寻址，并构造 InterAgentCommunication 显式传递消息","V2 彻底放弃了 ThreadId 概念，所有底层的网络调用完全依靠进程名识别","V2 将所有的子 Agent 合并到一个全局黑板（Blackboard）上进行无锁的共享内存读写"],correct:1,explanation:"V1 主要依靠分配的 ThreadId 进行硬绑定通信；V2 则引入了类似绝对路径的 AgentPath 进行更结构化的寻址，并使用显式的 Mailbox 消息（InterAgentCommunication）。"},{question:"为了防止子 Agent 被模型因为幻觉无限嵌套派生导致资源耗尽，Codex 在 V2 机制中主要依赖哪种防御手段？",options:["在 ThreadManager 中设置硬性的嵌套深度限制（Depth Limit）","在 AgentRegistry 中引入 max_concurrent_threads_per_session 进行总并发数限制","强制限制所有子 Agent 运行在内存低于 128MB 的 Docker 容器内","在模型层面修改 System Prompt，警告其“不准连续派生超过 3 个子任务”"],correct:1,explanation:"V1 的主力防线是 Depth Limit，但在 V2 中为了支持更灵活的网状协作，某些路径会忽略深度限制，转而依靠 AgentRegistry 的 reserve_spawn_slot 进行总并发线程数限制。"},{question:"对比早期的“全局共享黑板（Blackboard）”模式，Codex 的多 Agent 机制在工程上的核心优势是什么？",options:["极大地简化了代码实现，使得 Agent 的启动速度提升了数个数量级","更接近 Actor 式的显式消息传递，将会话状态强隔离，避免了并发脏读写引发的状态冲突","允许所有 Agent 实时共享同一个庞大的 Prompt 缓存池，降低 API 调用成本","使得系统能够完全脱离底层操作系统运行，实现真正意义上的跨平台编译分发"],correct:1,explanation:"黑板模式在并发量大时极易发生脏读写。Codex 通过接近 Actor 模型的设计，利用 CodexThread 实现了强隔离，并通过 InterAgentCommunication 进行安全的解耦通信。"}];return(c,e)=>{const s=t("Quiz");return i(),n("div",null,[e[0]||(e[0]=o("",50)),r(s,{questions:a})])}}});export{k as __pageData,A as default};
